// MCP server for the fork wiki. Cloudflare Pages Function served at /mcp.
// Implements the MCP Streamable HTTP transport (JSON responses) with zero
// dependencies: it loads the static /mcp/resources.json generated by Astro
// (src/pages/mcp/resources.json.ts) via the Pages ASSETS binding.
//
// Tools:
//   list_guides  — all docs pages (title, path, summary)
//   get_guide    — full markdown of one guide, identical to the published source
//   search_docs  — keyword search over the same corpus

interface Guide {
  slug: string;
  title: string;
  description: string;
  path: string;
  markdown: string;
}

interface Env {
  ASSETS: { fetch: typeof fetch };
}

interface JsonRpcRequest {
  jsonrpc?: string;
  id?: string | number | null;
  method?: string;
  params?: Record<string, unknown>;
}

const PROTOCOL_VERSION = "2025-06-18";
const SERVER_INFO = { name: "fork-kit", version: "0.1.0" };

const TOOLS = [
  {
    name: "list_guides",
    description:
      "List all fork-kit wiki pages (guides, references, instance list) with title, URL path, and summary.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "get_guide",
    description:
      "Get the full markdown source of a fork-kit wiki page by slug (e.g. 'guides/room-tba', 'guides/website', 'guides/new-campus-org', 'keep-in-sync', 'instances').",
    inputSchema: {
      type: "object",
      properties: {
        slug: { type: "string", description: "Doc slug, e.g. 'guides/room-tba'" },
      },
      required: ["slug"],
      additionalProperties: false,
    },
  },
  {
    name: "search_docs",
    description:
      "Keyword search over the fork-kit wiki corpus. Returns matching pages with snippets.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "Search terms, e.g. 'fork website'" },
      },
      required: ["query"],
      additionalProperties: false,
    },
  },
];

let guidesPromise: Promise<Guide[]> | null = null;

function loadGuides(env: Env, requestUrl: URL): Promise<Guide[]> {
  guidesPromise ??= (async () => {
    const res = await env.ASSETS.fetch(new URL("/mcp/resources.json", requestUrl));
    if (!res.ok) throw new Error(`resources.json fetch failed: ${res.status}`);
    const data = (await res.json()) as { guides: Guide[] };
    return data.guides;
  })();
  return guidesPromise;
}

function textResult(payload: unknown) {
  const text = typeof payload === "string" ? payload : JSON.stringify(payload, null, 2);
  return { content: [{ type: "text" as const, text }] };
}

function errorResult(message: string) {
  return { content: [{ type: "text" as const, text: message }], isError: true };
}

function callTool(name: string, args: Record<string, unknown>, guides: Guide[]) {
  switch (name) {
    case "list_guides":
      return textResult(
        guides.map(({ slug, title, description, path }) => ({ slug, title, description, path })),
      );

    case "get_guide": {
      const slug = String(args.slug ?? "").replace(/^\/+|\/+$/g, "");
      const guide = guides.find((g) => g.slug === slug);
      if (!guide) {
        return errorResult(
          `Guide '${slug}' not found. Call list_guides for available slugs.`,
        );
      }
      return textResult(
        `# ${guide.title}\nPath: ${guide.path}\n\n${guide.markdown}`,
      );
    }

    case "search_docs": {
      const query = String(args.query ?? "").trim().toLowerCase();
      if (!query) return errorResult("Empty query.");
      const terms = query.split(/\s+/).filter(Boolean);
      const matches = guides
        .map((g) => {
          const haystack = `${g.title}\n${g.description}\n${g.markdown}`.toLowerCase();
          const score = terms.reduce((n, t) => n + (haystack.includes(t) ? 1 : 0), 0);
          return { g, score };
        })
        .filter((m) => m.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 10)
        .map(({ g }) => ({
          slug: g.slug,
          title: g.title,
          path: g.path,
          description: g.description,
        }));
      return textResult(matches.length ? matches : `No matches for '${query}'.`);
    }

    default:
      return errorResult(`Unknown tool: ${name}`);
  }
}

function rpcResult(id: JsonRpcRequest["id"], result: unknown) {
  return { jsonrpc: "2.0", id: id ?? null, result };
}

function rpcError(id: JsonRpcRequest["id"], code: number, message: string) {
  return { jsonrpc: "2.0", id: id ?? null, error: { code, message } };
}

async function handleRpc(
  msg: JsonRpcRequest,
  env: Env,
  requestUrl: URL,
): Promise<object | null> {
  // Notifications have no id and expect no response.
  if (msg.id === undefined || msg.id === null) return null;

  switch (msg.method) {
    case "initialize":
      return rpcResult(msg.id, {
        protocolVersion: PROTOCOL_VERSION,
        capabilities: { tools: {} },
        serverInfo: SERVER_INFO,
      });

    case "ping":
      return rpcResult(msg.id, {});

    case "tools/list":
      return rpcResult(msg.id, { tools: TOOLS });

    case "tools/call": {
      const params = msg.params ?? {};
      const name = String(params.name ?? "");
      const args = (params.arguments ?? {}) as Record<string, unknown>;
      const guides = await loadGuides(env, requestUrl);
      return rpcResult(msg.id, callTool(name, args, guides));
    }

    default:
      return rpcError(msg.id, -32601, `Method not found: ${msg.method}`);
  }
}

export async function onRequestPost(context: {
  request: Request;
  env: Env;
}): Promise<Response> {
  const { request, env } = context;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json(rpcError(null, -32700, "Parse error"), { status: 400 });
  }

  const messages = Array.isArray(body) ? body : [body];
  const responses = (
    await Promise.all(
      messages.map((m) => handleRpc(m as JsonRpcRequest, env, new URL(request.url))),
    )
  ).filter((r): r is object => r !== null);

  if (responses.length === 0) return new Response(null, { status: 202 });
  return Response.json(Array.isArray(body) ? responses : responses[0]);
}

export function onRequestGet(): Response {
  return Response.json(
    {
      name: SERVER_INFO.name,
      protocol: "mcp-streamable-http",
      endpoint: "/mcp",
      resources: "/mcp/resources.json",
    },
    { headers: { "access-control-allow-origin": "*" } },
  );
}
